static Bounds BoundsOf(GameObject g){var rr=g.GetComponentsInChildren<Renderer>();bool first=true;Bounds b=new Bounds();foreach(var r in rr){if(r is ParticleSystemRenderer)continue;if(first){b=r.bounds;first=false;}else b.Encapsulate(r.bounds);}if(first)throw new Exception("No render bounds "+g.name);return b;}
static GameObject Put(string kind,string prefab,string label,float x,float z,float yaw,Vector3 target){var asset=AssetDatabase.LoadAssetAtPath<GameObject>(AssetsRoot+prefab);if(!asset)throw new Exception("Missing prefab "+prefab);var g=(GameObject)PrefabUtility.InstantiatePrefab(asset);g.name=label;g.transform.SetParent(placed,false);g.transform.rotation=Quaternion.identity;var before=BoundsOf(g);if(target!=Vector3.zero)g.transform.localScale=Vector3.Scale(g.transform.localScale,new Vector3(target.x/before.size.x,target.y/before.size.y,target.z/before.size.z));g.transform.rotation=Quaternion.Euler(0,yaw,0);var b=BoundsOf(g);g.transform.position+=new Vector3(x-b.center.x,-b.min.y,z-b.center.z);b=BoundsOf(g);if(!counts.ContainsKey(kind))counts[kind]=0;counts[kind]++;report.AppendLine("| "+label+" | "+kind+" | "+g.transform.position.ToString("F1")+" | "+yaw+" | "+b.size.ToString("F1")+" | "+g.transform.localScale.ToString("F3")+" |");if(b.min.x<150&&b.max.x> -150&&b.min.z<250&&b.max.z> -250){clearViolations++;Debug.LogError("Combat intrusion: "+label);}return g;}
static void Missing(Transform parent,string name,Vector3 p,Vector3 size){var g=new GameObject("MISSING_"+name+"_Size"+size);g.transform.SetParent(parent,false);g.transform.position=p;}
